import {chromium,webkit} from 'playwright';import fs from 'node:fs';import assert from 'node:assert/strict';const engine=process.env.BROWSER??'chromium',out=`qa-output/${engine}`;fs.mkdirSync(out,{recursive:true});const browser=await({chromium,webkit}[engine]).launch({headless:true,args:engine==='chromium'?['--use-angle=swiftshader']:[]});const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});page.setDefaultTimeout(120000);const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});let report={engine,stage:'02 structural candidate, visual acceptance pending'};try{await page.goto('http://127.0.0.1:8765/coffee.html',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.__plantStudy?.coffeeReady);await page.waitForTimeout(1000);await page.evaluate(()=>window.__plantStudy.setTime(27));await page.screenshot({path:`${out}/coffee-27-mature.png`});await page.locator('#root-cut').check();const frames=[];for(const t of [0,1,3,6,10,15,21,27,30]){await page.evaluate(t=>window.__plantStudy.setTime(t),t);const e=await page.evaluate(()=>window.__plantStudy.study.graph.evidence());assert.ok(e.connected);assert.ok(e.activeAttachmentsValid);frames.push({time:t,...e});if([0,3,10,21,30].includes(t))await page.screenshot({path:`${out}/coffee-${String(t).padStart(2,'0')}-root-cut.png`});}await page.locator('#root-cut').uncheck();await page.locator('#near').click();await page.waitForTimeout(350);await page.screenshot({path:`${out}/coffee-macro-front.png`});await page.locator('#light').evaluate(el=>el.value='135');await page.locator('#light').dispatchEvent('input');await page.waitForTimeout(350);await page.screenshot({path:`${out}/coffee-macro-back.png`});assert.equal(frames.at(-1).axisCount,67);assert.equal(frames.at(-1).wholeObjectScaling,false);assert.deepEqual(errors,[]);report={...report,passed:true,frames,errors};}catch(e){report={...report,passed:false,error:e.stack,errors};await page.screenshot({path:`${out}/coffee-failure.png`}).catch(()=>{});throw e;}finally{fs.writeFileSync(`${out}/coffee-result.json`,JSON.stringify(report,null,2));await browser.close();}
